#include "fur_root_distribution_candidate.h"
#include <iostream>
int main(){try{std::vector<GeometryDeformedVertexCandidate>vertices(6);vertices[0].position={0,0,0};vertices[1].position={1,0,0};vertices[2].position={0,1,0};vertices[3].position={10,0,0};vertices[4].position={12,0,0};vertices[5].position={10,2,0};for(auto&v:vertices)v.normal={0,0,1};std::vector<std::array<uint32_t,3>>triangles{{0,1,2},{3,4,5},{0,0,0}};auto roots=distributeFurRootsCandidate(vertices,triangles,10000,2,123);auto prefix=distributeFurRootsCandidate(vertices,triangles,100,2,123);auto changed=distributeFurRootsCandidate(vertices,triangles,100,2,124);size_t small=0;bool seedChanged=false;for(size_t i=0;i<roots.size();++i){if(roots[i].vertices==triangles[0])++small;else if(roots[i].vertices!=triangles[1])throw std::runtime_error("degenerate triangle selected");if(i<prefix.size()){if(roots[i].vertices!=prefix[i].vertices||roots[i].weights!=prefix[i].weights)throw std::runtime_error("density changed prior roots");seedChanged|=prefix[i].weights!=changed[i].weights;}}if(!seedChanged||small<1800||small>2200)throw std::runtime_error("area weighting or seed mismatch");auto guides=sampleFurSurfaceGuidesCandidate(roots,vertices);for(const auto&guide:guides)if(std::fabs(guide.tip[2]-guide.root[2]-2)>1e-5)throw std::runtime_error("distributed length mismatch");bool rejected=false;try{distributeFurRootsCandidate(vertices,{{0,0,0}},1,2,123);}catch(const std::runtime_error&){rejected=true;}if(!rejected)throw std::runtime_error("zero-area surface accepted");std::cout<<"fur_root_distribution_count="<<roots.size()<<" small_triangle_count="<<small<<" area_ratio=1:4 prefix_stable=true seed_changes=true degenerate_rejected=true\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
